export const envelope = [22, 20, 22];

export default function build(api) {
  const [W, H, D] = api.size;
  const seatY = 4;

  // Theme palettes with robust fallbacks
  const woodPlanks = api.theme.wood?.planks || "minecraft:spruce_planks";
  const woodLog = api.theme.wood?.log || "minecraft:spruce_log";
  const woodStripped = api.theme.wood?.stripped || "minecraft:stripped_spruce_log";
  const woodStairs = api.theme.wood?.stairs || "minecraft:spruce_stairs";
  const woodSlab = api.theme.wood?.slab || "minecraft:spruce_slab";
  const woodFence = api.theme.wood?.fence || "minecraft:spruce_fence";
  const woodDoor = api.theme.wood?.door || "minecraft:spruce_door";
  const woodTrapdoor = api.theme.wood?.trapdoor || "minecraft:spruce_trapdoor";

  const stonePrimary = api.theme.stone?.primary || "minecraft:stone_bricks";
  const stoneAccent = api.theme.stone?.accent || "minecraft:cobblestone";
  const stoneStairs = api.theme.stone?.stairs || "minecraft:stone_brick_stairs";
  const stoneSlab = api.theme.stone?.slab || "minecraft:stone_brick_slab";
  const stoneWall = api.theme.stone?.wall || "minecraft:cobblestone_wall";

  const roofStairs = api.theme.roof?.stairs || woodStairs;
  const roofSlab = api.theme.roof?.slab || woodSlab;
  const roofSolid = api.theme.roof?.solid || woodPlanks;

  const groundPlinth = api.theme.ground?.plinth || stoneAccent;

  function state(block, st) {
    if (!st) return block;
    const base = block.includes("[") ? block.slice(0, block.indexOf("[")) : block;
    return `${base}[${st}]`;
  }

  function set(x, y, z, block) {
    if (x < 0 || x >= W || y < 0 || y >= H || z < 0 || z >= D) return;
    api.set(x, y, z, block);
  }

  function fill(x1, y1, z1, x2, y2, z2, block) {
    const minX = Math.min(x1, x2), maxX = Math.max(x1, x2);
    const minY = Math.min(y1, y2), maxY = Math.max(y1, y2);
    const minZ = Math.min(z1, z2), maxZ = Math.max(z1, z2);
    for (let x = minX; x <= maxX; x++) {
      for (let y = minY; y <= maxY; y++) {
        for (let z = minZ; z <= maxZ; z++) {
          set(x, y, z, block);
        }
      }
    }
  }

  function getGroundY(x, z) {
    return Math.max(0, Math.min(seatY + Math.round(api.heightAt(x, z)), H - 1));
  }

  // Terrain-conforming pier reaching real ground
  function buildPier(x, z, topY, timberBlock = woodLog, stoneBlock = stonePrimary) {
    const gy = getGroundY(x, z);
    const bottomY = Math.min(gy, seatY);
    const maxTop = Math.max(gy, topY);

    for (let y = bottomY; y <= maxTop; y++) {
      if (y <= gy || y < seatY) {
        set(x, y, z, stoneBlock);
      } else if (y <= topY) {
        set(x, y, z, timberBlock);
      }
    }
  }

  function buildRetainingWall(x1, z1, x2, z2, topY) {
    const dx = Math.sign(x2 - x1);
    const dz = Math.sign(z2 - z1);
    const len = Math.max(Math.abs(x2 - x1), Math.abs(z2 - z1));
    for (let i = 0; i <= len; i++) {
      const x = x1 + dx * i;
      const z = z1 + dz * i;
      const gy = getGroundY(x, z);
      const lowY = Math.min(gy, seatY);
      const highY = Math.max(gy, topY);
      for (let y = lowY; y <= highY; y++) {
        if (y <= gy || y <= seatY) {
          set(x, y, z, groundPlinth);
        }
      }
    }
  }

  // 1. FOUNDATIONS & SUB-STRUCTURE SHORING
  // Footprint perimeter retaining walls following hillside
  buildRetainingWall(4, 6, 20, 6, seatY);
  buildRetainingWall(4, 21, 20, 21, seatY + 4);
  buildRetainingWall(4, 6, 4, 21, seatY);
  buildRetainingWall(20, 6, 20, 21, seatY + 1);

  // Structural bent columns
  const bentZ = [2, 6, 10, 14, 18, 21];
  const colX = [4, 7, 14, 17];
  for (const z of bentZ) {
    for (const x of colX) {
      const top = z === 2 ? 11 : z === 21 ? 14 : 15;
      buildPier(x, z, top, state(woodLog, "axis=y"), stonePrimary);
    }
  }
  // Extra columns for operator cabin & infeed portal
  buildPier(20, 14, 14, state(woodLog, "axis=y"), stonePrimary);
  buildPier(20, 18, 14, state(woodLog, "axis=y"), stonePrimary);
  buildPier(10, 21, 14, state(woodLog, "axis=y"), stonePrimary);
  buildPier(11, 21, 14, state(woodLog, "axis=y"), stonePrimary);

  // 2. MAIN LOWER DECK & CANTILEVER PROW (Y = 4)
  // Longitudinal sills
  for (let z = 6; z <= 20; z++) {
    for (const x of [4, 7, 14, 17, 20]) {
      set(x, 4, z, state(woodLog, "axis=z"));
    }
  }
  // Transverse tie sills
  for (const z of [6, 10, 14, 18, 21]) {
    for (let x = 4; x <= 20; x++) {
      set(x, 4, z, state(woodLog, "axis=x"));
    }
  }
  // Solid timber flooring at Y = 4
  for (let x = 4; x <= 20; x++) {
    for (let z = 6; z <= 20; z++) {
      // Leave hopper discharge pit open at X = 9..12, Z = 7..10
      if (!(x >= 9 && x <= 12 && z >= 7 && z <= 10)) {
        set(x, 4, z, woodPlanks);
      }
    }
  }

  // Cantilevered inspection catwalks extending forward (Z = 2..5)
  for (let z = 2; z <= 5; z++) {
    for (let x = 6; x <= 8; x++) {
      set(x, 4, z, woodPlanks);
    }
    for (let x = 13; x <= 15; x++) {
      set(x, 4, z, woodPlanks);
    }
  }
  // Cross catwalk connecting tracks at Z = 4
  for (let x = 8; x <= 13; x++) {
    set(x, 4, 4, woodPlanks);
  }
  // Catwalk perimeter guardrails at Y = 5
  for (let z = 2; z <= 5; z++) {
    set(5, 5, z, woodFence);
    set(16, 5, z, woodFence);
  }
  set(6, 5, 2, woodFence);
  set(7, 5, 2, woodFence);
  set(8, 5, 2, woodFence);
  set(13, 5, 2, woodFence);
  set(14, 5, 2, woodFence);
  set(15, 5, 2, woodFence);
  for (let x = 9; x <= 12; x++) {
    set(x, 5, 3, woodFence);
  }

  // Diagonal support knees under the forward cantilever (Z = 2..5, Y = 1..3)
  for (let y = 1; y <= 3; y++) {
    const z = 6 - y;
    set(7, y, z, state(woodStairs, "facing=north,half=top"));
    set(14, y, z, state(woodStairs, "facing=north,half=top"));
  }

  // 3. CANTILEVER BOOMS & OVERHEAD GANTRY (Z = 0..6, Y = 11..13)
  // Heavy timber boom arms extending to Z = 0
  for (let z = 0; z <= 6; z++) {
    set(7, 12, z, state(woodLog, "axis=z"));
    set(14, 12, z, state(woodLog, "axis=z"));
  }
  for (let x = 4; x <= 17; x++) {
    set(x, 12, 1, state(woodLog, "axis=x"));
    set(x, 12, 3, state(woodLog, "axis=x"));
    set(x, 12, 6, state(woodLog, "axis=x"));
  }

  // Diagonal raking A-frame shear legs from forward bent to boom tips
  set(4, 9, 4, state(woodStairs, "facing=north,half=bottom"));
  set(4, 10, 3, state(woodLog, "axis=y"));
  set(4, 11, 2, state(woodStairs, "facing=north,half=bottom"));
  set(17, 9, 4, state(woodStairs, "facing=north,half=bottom"));
  set(17, 10, 3, state(woodLog, "axis=y"));
  set(17, 11, 2, state(woodStairs, "facing=north,half=bottom"));

  // Tension tie chains pulling booms back to main tower peak
  for (let i = 0; i <= 3; i++) {
    set(7, 13 + i, 1 + i, "minecraft:chain[axis=y]");
    set(14, 13 + i, 1 + i, "minecraft:chain[axis=y]");
  }

  // Cantilever prow lanterns
  set(7, 11, 0, "minecraft:chain[axis=y]");
  set(7, 10, 0, "minecraft:lantern[hanging=true]");
  set(14, 11, 0, "minecraft:chain[axis=y]");
  set(14, 10, 0, "minecraft:lantern[hanging=true]");

  // 4. UPPER BENT FRAMING & TIE GAFES (Y = 8 & Y = 14)
  for (const z of [6, 10, 14, 18]) {
    for (let x = 4; x <= 17; x++) {
      set(x, 8, z, state(woodStripped, "axis=x"));
      set(x, 14, z, state(woodLog, "axis=x"));
    }
  }
  // Longitudinal top plates along Z
  for (let z = 6; z <= 20; z++) {
    for (const x of [4, 7, 14, 17]) {
      set(x, 14, z, state(woodLog, "axis=z"));
    }
  }

  // Catwalks flanking machinery at Y = 8
  for (let z = 6; z <= 14; z++) {
    for (let x = 4; x <= 6; x++) {
      set(x, 8, z, woodPlanks);
    }
    for (let x = 15; x <= 17; x++) {
      set(x, 8, z, woodPlanks);
    }
    // Safety railings
    set(4, 9, z, woodFence);
    set(17, 9, z, woodFence);
  }

  // Stairs from deck Y = 4 to upper level Y = 8
  for (let i = 0; i < 4; i++) {
    set(5, 5 + i, 15 - i, state(woodStairs, "facing=north,half=bottom"));
    set(5, 4 + i, 15 - i, stonePrimary);
  }

  // 5. ORE HOPPER & DISCHARGE CHUTES (X = 9..12, Z = 6..10, Y = 5..8)
  // Hopper funnel walls
  for (let x = 8; x <= 13; x++) {
    set(x, 8, 6, state(woodLog, "axis=x"));
    set(x, 8, 10, state(woodLog, "axis=x"));
  }
  for (let z = 6; z <= 10; z++) {
    set(8, 8, z, state(woodLog, "axis=z"));
    set(13, 8, z, state(woodLog, "axis=z"));
  }
  // Inverted hopper slopes
  for (let x = 9; x <= 12; x++) {
    set(x, 7, 7, state(woodStairs, "facing=south,half=top"));
    set(x, 7, 9, state(woodStairs, "facing=north,half=top"));
    set(x, 6, 7, state(woodStairs, "facing=south,half=top"));
    set(x, 6, 9, state(woodStairs, "facing=north,half=top"));
  }
  for (let z = 7; z <= 9; z++) {
    set(9, 7, z, state(woodStairs, "facing=east,half=top"));
    set(12, 7, z, state(woodStairs, "facing=west,half=top"));
    set(9, 6, z, state(woodStairs, "facing=east,half=top"));
    set(12, 6, z, state(woodStairs, "facing=west,half=top"));
  }
  // Raw silver ore inside hopper
  set(10, 7, 8, "minecraft:raw_iron_block");
  set(11, 7, 8, stoneAccent);
  set(10, 6, 8, stoneAccent);
  set(11, 6, 8, "minecraft:raw_iron_block");

  // Side discharge chutes toward tramway bucket positions
  set(8, 5, 8, state(woodStairs, "facing=east,half=bottom"));
  set(7, 5, 8, "minecraft:hopper[facing=west]");
  set(13, 5, 8, state(woodStairs, "facing=west,half=bottom"));
  set(14, 5, 8, "minecraft:hopper[facing=east]");

  // 6. THE GREAT BULLWHEEL (HORIZONTAL CABLE DRIVE) (Center X=10.5, Z=11, Y=9)
  // Vertical iron spindle & bearings
  for (let y = 8; y <= 12; y++) {
    set(10, y, 11, state(woodStripped, "axis=y"));
    set(11, y, 11, state(woodStripped, "axis=y"));
  }
  set(10, 8, 11, "minecraft:iron_block");
  set(11, 8, 11, "minecraft:iron_block");
  set(10, 10, 11, "minecraft:grindstone[face=floor,facing=north]");
  set(11, 10, 11, "minecraft:grindstone[face=floor,facing=north]");

  // Bullwheel spokes radiating outward at Y = 9
  set(10, 9, 10, woodFence);
  set(11, 9, 10, woodFence);
  set(10, 9, 9, woodFence);
  set(11, 9, 9, woodFence);

  set(10, 9, 12, woodFence);
  set(11, 9, 12, woodFence);
  set(10, 9, 13, woodFence);
  set(11, 9, 13, woodFence);

  set(9, 9, 11, woodFence);
  set(8, 9, 11, woodFence);
  set(12, 9, 11, woodFence);
  set(13, 9, 11, woodFence);

  set(9, 9, 10, "minecraft:iron_bars");
  set(9, 9, 12, "minecraft:iron_bars");
  set(12, 9, 10, "minecraft:iron_bars");
  set(12, 9, 12, "minecraft:iron_bars");

  // Bullwheel octagonal rim (Diameter 7 blocks at Y = 9)
  const rimCoords = [
    [9, 8], [10, 8], [11, 8], [12, 8],
    [8, 9], [13, 9],
    [7, 10], [7, 11], [7, 12],
    [14, 10], [14, 11], [14, 12],
    [8, 13], [13, 13],
    [9, 14], [10, 14], [11, 14], [12, 14]
  ];
  for (const [rx, rz] of rimCoords) {
    set(rx, 9, rz, state(woodSlab, "type=top"));
  }

  // Continuous wire rope wrapped around the Bullwheel
  for (let z = 10; z <= 12; z++) {
    set(7, 9, z, "minecraft:chain[axis=z]");
    set(14, 9, z, "minecraft:chain[axis=z]");
  }
  set(8, 9, 13, "minecraft:chain[axis=x]");
  set(9, 9, 14, "minecraft:chain[axis=x]");
  set(10, 9, 14, "minecraft:chain[axis=x]");
  set(11, 9, 14, "minecraft:chain[axis=x]");
  set(12, 9, 14, "minecraft:chain[axis=x]");
  set(13, 9, 13, "minecraft:chain[axis=x]");

  // Drive pinion gear & transmission shaft connecting south
  set(10, 9, 15, "minecraft:iron_block");
  set(11, 9, 15, "minecraft:iron_block");
  set(10, 10, 15, "minecraft:grindstone[face=floor,facing=north]");
  set(11, 10, 15, "minecraft:grindstone[face=floor,facing=north]");

  // 7. CABLE TENSION CARRIAGE & COUNTERWEIGHT RIG (Z = 14..18)
  // Sliding timber tension rails
  for (let z = 14; z <= 17; z++) {
    set(9, 8, z, state(woodStripped, "axis=z"));
    set(12, 8, z, state(woodStripped, "axis=z"));
    set(9, 9, z, "minecraft:grindstone[face=floor,facing=north]");
    set(12, 9, z, "minecraft:grindstone[face=floor,facing=north]");
  }
  // Overhead counterweight gallows beam at Y = 14
  for (let x = 8; x <= 13; x++) {
    set(x, 14, 16, state(woodLog, "axis=x"));
  }
  set(10, 14, 16, "minecraft:grindstone[face=ceiling,facing=north]");
  set(11, 14, 16, "minecraft:grindstone[face=ceiling,facing=north]");

  // Suspension chains dropping from overhead pulleys to weight box
  for (let y = 9; y <= 13; y++) {
    set(10, y, 16, "minecraft:chain[axis=y]");
    set(11, y, 16, "minecraft:chain[axis=y]");
  }
  // Heavy timber & iron counterweight ballast box (Y = 5..8)
  for (let y = 5; y <= 8; y++) {
    set(9, y, 15, state(woodLog, "axis=y"));
    set(12, y, 15, state(woodLog, "axis=y"));
    set(9, y, 17, state(woodLog, "axis=y"));
    set(12, y, 17, state(woodLog, "axis=y"));
    // Ballast fill
    set(10, y, 15, stonePrimary);
    set(11, y, 15, stonePrimary);
    set(10, y, 17, stonePrimary);
    set(11, y, 17, stonePrimary);
    set(10, y, 16, stoneAccent);
    set(11, y, 16, stoneAccent);
    set(9, y, 16, "minecraft:iron_bars");
    set(12, y, 16, "minecraft:iron_bars");
  }

  // 8. CABLE TRACKS & SUSPENDED SILVER ORE BUCKETS
  // Main aerial track cables stretching north (Y = 10)
  for (let z = 0; z <= 10; z++) {
    set(7, 10, z, "minecraft:chain[axis=z]");
    set(14, 10, z, "minecraft:chain[axis=z]");
  }
  // Forward guide sheaves at Z = 2
  set(7, 11, 2, "minecraft:grindstone[face=ceiling,facing=north]");
  set(14, 11, 2, "minecraft:grindstone[face=ceiling,facing=north]");

  // Bucket 1: Outgoing Loaded Silver Ore Bucket on North Gantry (X = 14, Z = 1)
  set(14, 10, 1, "minecraft:hopper[facing=down]");
  set(14, 9, 1, "minecraft:iron_bars");
  set(14, 8, 1, "minecraft:iron_bars");
  set(14, 7, 1, "minecraft:cauldron");
  set(14, 8, 0, state(woodTrapdoor, "facing=south,half=bottom,open=false"));

  // Bucket 2: Inbound Bucket at Loading Chute (X = 7, Z = 7)
  set(7, 10, 7, "minecraft:hopper[facing=down]");
  set(7, 9, 7, "minecraft:iron_bars");
  set(7, 8, 7, "minecraft:iron_bars");
  set(7, 7, 7, "minecraft:cauldron");
  set(6, 7, 7, state(woodTrapdoor, "facing=east,half=top,open=false"));

  // 9. OPERATOR CABIN / ASSAY OFFICE (X = 14..20, Z = 13..19, Y = 4..9)
  // Floor at Y = 4
  fill(14, 4, 13, 20, 4, 19, woodPlanks);

  // Cabin timber walls
  for (let y = 5; y <= 8; y++) {
    // East wall
    set(20, y, 13, state(woodLog, "axis=y"));
    set(20, y, 19, state(woodLog, "axis=y"));
    for (let z = 14; z <= 18; z++) {
      set(20, y, z, z === 16 && (y === 6 || y === 7) ? woodFence : woodPlanks);
    }
    // North wall
    for (let x = 15; x <= 19; x++) {
      set(x, y, 13, (x >= 16 && x <= 18) && (y === 6 || y === 7) ? "minecraft:iron_bars" : woodPlanks);
    }
    // South wall (doorway at X = 17)
    for (let x = 15; x <= 19; x++) {
      if (x === 17 && (y === 5 || y === 6)) {
        // Leave doorway open for player / compiler
      } else {
        set(x, y, 19, woodPlanks);
      }
    }
    // West wall overlooking machinery
    set(14, y, 13, state(woodLog, "axis=y"));
    set(14, y, 19, state(woodLog, "axis=y"));
    for (let z = 14; z <= 18; z++) {
      set(14, y, z, z === 16 && (y === 6 || y === 7) ? "minecraft:iron_bars" : woodPlanks);
    }
  }
  // Cabin ceiling at Y = 9
  fill(14, 9, 13, 20, 9, 19, woodPlanks);

  // Door at south entrance
  set(17, 5, 19, state(woodDoor, "facing=south,half=lower,hinge=left"));
  set(17, 6, 19, state(woodDoor, "facing=south,half=upper,hinge=left"));
  // Entrance porch lantern
  set(17, 7, 20, "minecraft:lantern[hanging=true]");

  // 10. ELEVATED MINE ADIT TRESTLE & ORE INFEED (Z = 17..21, X = 9..12, Y = 8..9)
  for (let z = 11; z <= 21; z++) {
    for (let x = 9; x <= 12; x++) {
      set(x, 8, z, woodPlanks);
    }
    set(9, 7, z, state(woodLog, "axis=z"));
    set(12, 7, z, state(woodLog, "axis=z"));
    // Side guard fences
    if (z >= 12) {
      set(9, 9, z, woodFence);
      set(12, 9, z, woodFence);
    }
    // Mine rail track
    if (z >= 12) {
      set(10, 9, z, "minecraft:rail[shape=north_south]");
      set(11, 9, z, "minecraft:rail[shape=north_south]");
    }
  }
  // Rail bumper stop above hopper lip at Z = 11
  set(10, 9, 11, state(woodLog, "axis=x"));
  set(11, 9, 11, state(woodLog, "axis=x"));
  set(10, 10, 11, "minecraft:iron_bars");
  set(11, 10, 11, "minecraft:iron_bars");

  // 11. SUPERSTRUCTURE GABLED ROOF & CLERESTORY MONITOR (Y = 12..19)
  for (let z = 5; z <= 20; z++) {
    // West Roof Slope
    set(2, 13, z, state(roofStairs, "facing=east,half=bottom"));
    set(3, 13, z, roofSolid);
    set(4, 14, z, state(roofStairs, "facing=east,half=bottom"));
    set(5, 14, z, roofSolid);
    set(6, 15, z, state(roofStairs, "facing=east,half=bottom"));
    set(7, 15, z, roofSolid);
    set(8, 16, z, state(roofStairs, "facing=east,half=bottom"));
    set(9, 16, z, roofSolid);
    set(10, 17, z, state(roofStairs, "facing=east,half=bottom"));

    // East Roof Slope
    set(19, 13, z, state(roofStairs, "facing=west,half=bottom"));
    set(18, 13, z, roofSolid);
    set(17, 14, z, state(roofStairs, "facing=west,half=bottom"));
    set(16, 14, z, roofSolid);
    set(15, 15, z, state(roofStairs, "facing=west,half=bottom"));
    set(14, 15, z, roofSolid);
    set(13, 16, z, state(roofStairs, "facing=west,half=bottom"));
    set(12, 16, z, roofSolid);
    set(11, 17, z, state(roofStairs, "facing=west,half=bottom"));

    // Ridge cap on non-monitor sections
    if (z < 8 || z > 15) {
      set(10, 17, z, roofSolid);
      set(11, 17, z, roofSolid);
      set(10, 18, z, state(roofSlab, "type=bottom"));
      set(11, 18, z, state(roofSlab, "type=bottom"));
    }

    // Under-eave support brackets
    if (z === 5 || z === 20) {
      set(2, 12, z, state(woodStairs, "facing=east,half=top"));
      set(19, 12, z, state(woodStairs, "facing=west,half=top"));
    }
  }

  // Clerestory Monitor Cupola (Dust/Steam Ventilation) (Z = 8..15, Y = 17..19)
  for (let z = 8; z <= 15; z++) {
    // Louver vents
    set(9, 17, z, woodFence);
    set(12, 17, z, woodFence);
    // Monitor gabled roof
    set(9, 18, z, state(roofStairs, "facing=east,half=bottom"));
    set(10, 18, z, roofSolid);
    set(11, 18, z, roofSolid);
    set(12, 18, z, state(roofStairs, "facing=west,half=bottom"));
    set(10, 19, z, state(roofSlab, "type=bottom"));
    set(11, 19, z, state(roofSlab, "type=bottom"));
  }

  // Gable Walls & Open Truss Arches
  // South Gable Wall (Z = 20)
  for (let y = 9; y <= 16; y++) {
    for (let x = 4; x <= 17; x++) {
      // Leave mine cart infeed portal open at X = 10..11, Y = 9..11
      if (!(x >= 10 && x <= 11 && y >= 9 && y <= 11)) {
        if (x === 4 || x === 7 || x === 14 || x === 17) {
          set(x, y, 20, state(woodLog, "axis=y"));
        } else if (y <= 16 - Math.abs(x - 10.5)) {
          set(x, y, 20, woodPlanks);
        }
      }
    }
  }

  // North Gable Truss Arch (Z = 5) - open for cable bucket clearance
  set(6, 14, 5, state(woodStairs, "facing=south,half=top"));
  set(8, 14, 5, state(woodStairs, "facing=south,half=top"));
  set(13, 14, 5, state(woodStairs, "facing=south,half=top"));
  set(15, 14, 5, state(woodStairs, "facing=south,half=top"));
  set(7, 15, 5, state(woodLog, "axis=y"));
  set(14, 15, 5, state(woodLog, "axis=y"));
  set(10, 16, 5, state(woodLog, "axis=x"));
  set(11, 16, 5, state(woodLog, "axis=x"));

  // South mountain cable tie-back stays
  set(7, 8, 21, stoneWall);
  set(14, 8, 21, stoneWall);
  set(7, 9, 21, "minecraft:chain[axis=z]");
  set(14, 9, 21, "minecraft:chain[axis=z]");

  return {
    name: "ore_tramway_terminal",
    seatY,
    anchors: {
      front: [10, 8, 0],
      door: [17, 5, 21],
      mine_infeed: [10, 9, 21]
    },
    interiors: [
      {
        min: [15, 5, 14],
        max: [19, 8, 18],
        kind: "quarters"
      }
    ]
  };
}

