export const envelope = [22, 18, 22];

export default function build(api) {
  const [W, H, D] = envelope;

  // Helper: safe block placement
  function setBlock(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D && block) {
      api.set(x, y, z, block);
    }
  }

  // Palette extraction from world theme
  const woodPlanks = api.theme.wood.planks || "minecraft:spruce_planks";
  const woodLog = api.theme.wood.log || "minecraft:spruce_log";
  const woodStripped = api.theme.wood.stripped || woodPlanks;
  const woodStairs = api.theme.wood.stairs || "minecraft:spruce_stairs";
  const woodSlab = api.theme.wood.slab || "minecraft:spruce_slab";
  const woodFence = api.theme.wood.fence || "minecraft:spruce_fence";
  const woodDoor = api.theme.wood.door || "minecraft:spruce_door";
  const woodTrapdoor = api.theme.wood.trapdoor || "minecraft:spruce_trapdoor";

  const stonePrimary = api.theme.stone.primary || "minecraft:stone_bricks";
  const stoneAccent = api.theme.stone.accent || "minecraft:cobblestone";
  const stoneStairs = api.theme.stone.stairs || "minecraft:stone_brick_stairs";
  const stoneSlab = api.theme.stone.slab || "minecraft:stone_brick_slab";
  const stoneWall = api.theme.stone.wall || "minecraft:cobblestone_wall";

  const roofStairs = api.theme.roof.stairs || woodStairs;
  const roofSlab = api.theme.roof.slab || woodSlab;
  const roofSolid = api.theme.roof.solid || woodPlanks;

  const plinth = api.theme.ground.plinth || stonePrimary;
  const pavement = api.theme.ground.pavement || stoneAccent;

  // Formatting helpers for block states
  function getLog(baseLog, axis = "y") {
    const id = baseLog ? baseLog.split("[")[0] : "minecraft:spruce_log";
    return `${id}[axis=${axis}]`;
  }
  function getStairs(baseStair, facing, half = "bottom") {
    const id = baseStair ? baseStair.split("[")[0] : "minecraft:spruce_stairs";
    return `${id}[facing=${facing},half=${half}]`;
  }
  function getSlab(baseSlab, type = "bottom") {
    const id = baseSlab ? baseSlab.split("[")[0] : "minecraft:spruce_slab";
    return `${id}[type=${type}]`;
  }

  const logY = getLog(woodLog, "y");
  const logX = getLog(woodLog, "x");
  const logZ = getLog(woodLog, "z");

  // Fill column down to terrain (Rule 6: Follow the ground you are given)
  function groundColumn(x, z, topY, block) {
    const groundH = Math.round(api.heightAt(x, z));
    const botY = Math.min(0, groundH);
    for (let y = botY; y <= topY; y++) {
      setBlock(x, y, z, block);
    }
  }

  // 1. Foundation & Railway Siding (Y = 0 to 1)
  for (let x = 0; x < W; x++) {
    for (let z = 8; z <= 13; z++) {
      groundColumn(x, z, 0, pavement);
    }
    // Railway lines running East-West under the hoppers
    setBlock(x, 1, 9, getSlab(stoneSlab, "bottom"));
    setBlock(x, 1, 10, "minecraft:rail[shape=east_west]");
    setBlock(x, 1, 11, "minecraft:rail[shape=east_west]");
    setBlock(x, 1, 12, getSlab(stoneSlab, "bottom"));
  }

  // 2. Heavy Masonry Footing Piers & Main Timber Bents
  const pierCols = [
    [2, 3, 6, 7], [7, 8, 6, 7], [13, 14, 6, 7], [18, 19, 6, 7],
    [2, 3, 11, 12], [7, 8, 11, 12], [13, 14, 11, 12], [18, 19, 11, 12],
    [2, 3, 16, 17], [7, 8, 16, 17], [13, 14, 16, 17], [18, 19, 16, 17]
  ];

  for (const [x1, x2, z1, z2] of pierCols) {
    for (let x = x1; x <= x2; x++) {
      for (let z = z1; z <= z2; z++) {
        groundColumn(x, z, 2, plinth);
        // Masonry plinth stepped top
        if (x === x1 || x === x2 || z === z1 || z === z2) {
          setBlock(x, 2, z, stonePrimary);
        }
      }
    }
  }

  // Timber vertical columns (Y = 3 to 11)
  const postCoords = [
    [3, 7], [8, 7], [13, 7], [18, 7],
    [3, 12], [8, 12], [13, 12], [18, 12],
    [3, 17], [8, 17], [13, 17], [18, 17]
  ];

  for (const [px, pz] of postCoords) {
    for (let y = 3; y <= 11; y++) {
      setBlock(px, y, pz, logY);
    }
    // Corner knee braces
    setBlock(px, 5, pz + 1, getStairs(woodStairs, "north", "top"));
    setBlock(px, 5, pz - 1, getStairs(woodStairs, "south", "top"));
  }

  // Intermediate Horizontal Girts & Beams at Y = 5 and Y = 11
  for (const pz of [7, 12, 17]) {
    for (let x = 3; x <= 18; x++) {
      setBlock(x, 5, pz, logX);
      setBlock(x, 11, pz, logX);
    }
  }
  for (const px of [3, 8, 13, 18]) {
    for (let z = 7; z <= 17; z++) {
      setBlock(px, 5, z, logZ);
      setBlock(px, 11, z, logZ);
    }
  }

  // 3. Trestle Ore Hoppers (Y = 5 to 11)
  // Two massive timber-framed bins: West (X: 4..7) and East (X: 14..17)
  const bins = [
    { x1: 4, x2: 7, cx: 5, cz: 10, fillY: 9 },
    { x1: 14, x2: 17, cx: 15, cz: 10, fillY: 8 }
  ];

  for (const bin of bins) {
    // Discharge hopper chute bottoms over railway siding (Y = 5)
    setBlock(bin.cx, 5, bin.cz, "minecraft:hopper[facing=down]");
    setBlock(bin.cx + 1, 5, bin.cz, "minecraft:hopper[facing=down]");
    setBlock(bin.cx, 4, bin.cz, "minecraft:iron_bars");
    setBlock(bin.cx + 1, 4, bin.cz, "minecraft:iron_bars");

    // Sloping timber bin walls (Y = 6 to 10)
    for (let y = 6; y <= 10; y++) {
      for (let x = bin.x1; x <= bin.x2; x++) {
        for (let z = 8; z <= 11; z++) {
          const isWall = (x === bin.x1 || x === bin.x2 || z === 8 || z === 11);
          if (isWall) {
            setBlock(x, y, z, woodPlanks);
          } else {
            // Inside bin: crushed silver ore (raw iron & dark stone pile)
            if (y <= bin.fillY) {
              const oreType = (x + y + z) % 3 === 0 ? "minecraft:raw_iron_block" : stoneAccent;
              setBlock(x, y, z, oreType);
            }
          }
        }
      }
    }

    // Heavy iron grizzly screens over bin tops (Y = 11)
    for (let x = bin.x1 + 1; x <= bin.x2 - 1; x++) {
      for (let z = 9; z <= 10; z++) {
        setBlock(x, 11, z, "minecraft:iron_bars");
      }
    }
  }

  // 4. Upper Terminal Deck (Y = 11)
  for (let x = 3; x <= 18; x++) {
    for (let z = 6; z <= 17; z++) {
      // Don't overwrite grizzly screens
      if (!((x >= 5 && x <= 6 && z >= 9 && z <= 10) || (x >= 15 && x <= 16 && z >= 9 && z <= 10))) {
        setBlock(x, 11, z, woodPlanks);
      }
    }
  }

  // North Tramway Gantry Extension (Z = 1 to 5)
  for (let x = 6; x <= 15; x++) {
    for (let z = 1; z <= 5; z++) {
      setBlock(x, 11, z, woodPlanks);
    }
  }
  // Cantilever timber support beams for gantry
  for (const gx of [7, 8, 13, 14]) {
    for (let z = 1; z <= 6; z++) {
      setBlock(gx, 10, z, logZ);
    }
    groundColumn(gx, 2, 10, plinth);
  }

  // Front cable guide pylon towers at Z = 2
  for (const px of [7, 14]) {
    for (let y = 11; y <= 16; y++) {
      setBlock(px, y, 2, logY);
    }
    setBlock(px, 16, 2, woodStripped);
    setBlock(px, 15, 1, getStairs(woodStairs, "south", "top"));
  }
  // Crosshead timber beam at gantry top
  for (let x = 7; x <= 14; x++) {
    setBlock(x, 16, 2, logX);
  }

  // Perimeter handrails on open deck edges
  for (let x = 6; x <= 15; x++) {
    setBlock(x, 12, 1, woodFence);
  }
  for (let z = 1; z <= 5; z++) {
    setBlock(6, 12, z, woodFence);
    setBlock(15, 12, z, woodFence);
  }
  for (let z = 6; z <= 17; z++) {
    setBlock(18, 12, z, woodFence);
  }

  // 5. Aerial Tramway Machinery, Cables & Buckets (Y = 12 to 16)
  // Incoming West Cable (Loaded Ore Buckets from Mountain)
  for (let z = 0; z <= 9; z++) {
    setBlock(7, 15, z, "minecraft:chain[axis=z]");
  }
  setBlock(7, 16, 2, "minecraft:grindstone[face=ceiling,facing=north]");

  // Incoming Loaded Ore Bucket (Z = 3)
  setBlock(7, 14, 3, "minecraft:chain[axis=y]");
  setBlock(7, 13, 3, woodFence);
  setBlock(7, 12, 3, "minecraft:cauldron");
  setBlock(7, 13, 3, "minecraft:raw_iron_block");

  // Bucket Discharge Point / Ore Tipping Mechanism over West Grizzly (Z = 9)
  setBlock(7, 14, 9, "minecraft:chain[axis=y]");
  setBlock(7, 13, 9, "minecraft:hopper[facing=down]");
  setBlock(7, 12, 9, "minecraft:raw_iron_block");
  setBlock(8, 13, 9, woodTrapdoor);

  // Outgoing East Cable (Empty Return Buckets)
  for (let z = 0; z <= 12; z++) {
    setBlock(14, 15, z, "minecraft:chain[axis=z]");
  }
  setBlock(14, 16, 2, "minecraft:grindstone[face=ceiling,facing=north]");

  // Empty Return Bucket (Z = 4)
  setBlock(14, 14, 4, "minecraft:chain[axis=y]");
  setBlock(14, 13, 4, woodFence);
  setBlock(14, 12, 4, "minecraft:cauldron");

  // Bullwheel / Cable Return Sheave Mechanism (X = 9..12, Z = 12..14, Y = 12..14)
  // Center drive axle
  for (let y = 11; y <= 15; y++) {
    setBlock(10, y, 13, stonePrimary);
    setBlock(11, y, 13, stonePrimary);
  }
  // Bullwheel rim & spokes
  const wheelBlocks = [
    [9, 14, 12], [10, 14, 12], [11, 14, 12], [12, 14, 12],
    [8, 14, 13], [13, 14, 13],
    [9, 14, 14], [10, 14, 14], [11, 14, 14], [12, 14, 14]
  ];
  for (const [wx, wy, wz] of wheelBlocks) {
    setBlock(wx, wy, wz, stoneAccent);
  }
  setBlock(10, 15, 13, "minecraft:grindstone[face=floor,facing=north]");
  setBlock(11, 15, 13, "minecraft:grindstone[face=floor,facing=north]");
  setBlock(10, 13, 14, "minecraft:chain[axis=y]");
  setBlock(11, 13, 14, "minecraft:chain[axis=y]");

  // 6. Assay Office & Winch Cabin (South-West: X = 3..8, Z = 13..17, Y = 11..16)
  for (let x = 3; x <= 8; x++) {
    for (let z = 13; z <= 17; z++) {
      const isPerimeter = (x === 3 || x === 8 || z === 13 || z === 17);
      if (isPerimeter) {
        for (let y = 12; y <= 15; y++) {
          setBlock(x, y, z, woodPlanks);
        }
      }
      setBlock(x, 15, z, woodPlanks); // Cabin ceiling
    }
  }

  // Cabin Windows & Doors
  setBlock(3, 13, 15, "minecraft:iron_bars");
  setBlock(3, 14, 15, "minecraft:iron_bars");
  setBlock(5, 13, 17, "minecraft:iron_bars");
  setBlock(6, 13, 17, "minecraft:iron_bars");
  setBlock(6, 13, 13, "minecraft:iron_bars"); // Lookout window toward bins

  // Cabin Doorway on East wall
  setBlock(8, 12, 15, "minecraft:spruce_door[facing=east,half=lower]");
  setBlock(8, 13, 15, "minecraft:spruce_door[facing=east,half=upper]");
  setBlock(8, 12, 14, woodPlanks);

  // 7. External Access Staircase (East Trestle: X = 19..20, Z = 13..19)
  for (const [sx, sz] of [[19, 13], [19, 18], [20, 13], [20, 18]]) {
    groundColumn(sx, sz, 10, plinth);
    setBlock(sx, 11, sz, logY);
  }

  // Lower flight (Ground to intermediate landing at Y = 5)
  for (let step = 0; step < 5; step++) {
    const y = 1 + step;
    const z = 18 - step;
    setBlock(20, y, z, getStairs(woodStairs, "north", "bottom"));
    setBlock(20, y - 1, z, woodPlanks);
    setBlock(21, y + 1, z, woodFence);
  }

  // Mid landing (Y = 5, Z = 13..14)
  setBlock(19, 5, 13, woodPlanks);
  setBlock(20, 5, 13, woodPlanks);
  setBlock(19, 5, 14, woodPlanks);
  setBlock(20, 5, 14, woodPlanks);
  setBlock(21, 6, 13, woodFence);
  setBlock(20, 6, 12, woodFence);

  // Upper flight (Y = 6 to 11)
  for (let step = 0; step < 6; step++) {
    const y = 6 + step;
    const z = 13 + step;
    setBlock(19, y, z, getStairs(woodStairs, "south", "bottom"));
    setBlock(19, y - 1, z, woodPlanks);
    setBlock(20, y + 1, z, woodFence);
  }

  // 8. Terminal Shed Gabled Roof (Y = 14 to 17)
  // Spans X: 2 to 19, Z: 6 to 18. Ridge at X = 10, 11, Y = 17
  for (let z = 6; z <= 18; z++) {
    // Eaves overhangs
    setBlock(2, 13, z, getSlab(roofSlab, "top"));
    setBlock(3, 13, z, getStairs(roofStairs, "west", "bottom"));
    setBlock(4, 14, z, getStairs(roofStairs, "west", "bottom"));
    setBlock(5, 14, z, getSlab(roofSlab, "top"));
    setBlock(6, 15, z, getStairs(roofStairs, "west", "bottom"));
    setBlock(7, 15, z, getSlab(roofSlab, "top"));
    setBlock(8, 16, z, getStairs(roofStairs, "west", "bottom"));
    setBlock(9, 16, z, getSlab(roofSlab, "top"));

    // Central Ridge (Y = 17)
    setBlock(10, 17, z, roofSolid);
    setBlock(11, 17, z, roofSolid);

    // East Slope
    setBlock(12, 16, z, getSlab(roofSlab, "top"));
    setBlock(13, 16, z, getStairs(roofStairs, "east", "bottom"));
    setBlock(14, 15, z, getSlab(roofSlab, "top"));
    setBlock(15, 15, z, getStairs(roofStairs, "east", "bottom"));
    setBlock(16, 14, z, getSlab(roofSlab, "top"));
    setBlock(17, 14, z, getStairs(roofStairs, "east", "bottom"));
    setBlock(18, 13, z, getStairs(roofStairs, "east", "bottom"));
    setBlock(19, 13, z, getSlab(roofSlab, "top"));

    // Roof truss ties at bent lines
    if (z === 7 || z === 12 || z === 17) {
      for (let x = 4; x <= 17; x++) {
        setBlock(x, 14, z, logX);
      }
      setBlock(10, 15, z, logY);
      setBlock(11, 15, z, logY);
      setBlock(10, 16, z, logY);
      setBlock(11, 16, z, logY);
    }
  }

  // South Gable Wall (Z = 18) - Timber siding
  for (let x = 4; x <= 17; x++) {
    for (let y = 12; y <= 15; y++) {
      if (!api.theme.wood.planks) continue;
      // Clad South facade
      if (x >= 4 && x <= 17 && y <= 16) {
        setBlock(x, y, 18, woodPlanks);
      }
    }
  }
  // Gable ventilation louver
  setBlock(10, 15, 18, woodTrapdoor);
  setBlock(11, 15, 18, woodTrapdoor);

  // 9. Industrial Lighting & Lanterns
  // Undercroft rail siding lanterns
  setBlock(8, 4, 7, "minecraft:lantern[hanging=true]");
  setBlock(13, 4, 7, "minecraft:lantern[hanging=true]");
  setBlock(8, 4, 12, "minecraft:lantern[hanging=true]");
  setBlock(13, 4, 12, "minecraft:lantern[hanging=true]");

  // Upper deck & Gantry lanterns
  setBlock(7, 15, 2, "minecraft:lantern[hanging=true]");
  setBlock(14, 15, 2, "minecraft:lantern[hanging=true]");
  setBlock(17, 13, 17, "minecraft:lantern[hanging=false]");

  return {
    name: "valley_discharge_terminal",
    seatY: 0,
    anchors: {
      front: [11, 0, 0],
      rail_west: [0, 1, 10],
      rail_east: [21, 1, 10],
      stair_entry: [20, 0, 19]
    },
    interiors: [
      {
        min: [4, 12, 14],
        max: [7, 14, 16],
        kind: "quarters"
      }
    ]
  };
}

ore_tramway_pylon.source:
export const envelope = [9, 28, 9];

export default function build(api) {
  const { theme, instance } = api;
  const varId = (instance ? instance.index : 0) % 6;

  // Resolve palette roles safely from theme
  const woodLog = theme.wood.log || "minecraft:spruce_log";
  const woodStripped = theme.wood.stripped || "minecraft:stripped_spruce_log";
  const woodPlanks = theme.wood.planks || "minecraft:spruce_planks";
  const woodStairs = theme.wood.stairs || "minecraft:spruce_stairs";
  const woodSlab = theme.wood.slab || "minecraft:spruce_slab";
  const woodFence = theme.wood.fence || "minecraft:spruce_fence";
  const woodTrapdoor = theme.wood.trapdoor || "minecraft:spruce_trapdoor";

  const stonePrimary = theme.stone.primary || "minecraft:stone_bricks";
  const stoneAccent = theme.stone.accent || "minecraft:cobblestone";
  const stoneStairs = theme.stone.stairs || "minecraft:stone_brick_stairs";
  const plinth = theme.ground.plinth || stoneAccent;

  const seatY = 7;

  // Block state helpers
  function idOf(b) {
    return b.split("[")[0];
  }

  function getStair(base, facing, half = "bottom", shape = "straight") {
    return `${idOf(base)}[facing=${facing},half=${half},shape=${shape}]`;
  }

  function getSlab(base, type = "bottom") {
    return `${idOf(base)}[type=${type}]`;
  }

  function getLog(base, axis = "y") {
    return `${idOf(base)}[axis=${axis}]`;
  }

  function getTrapdoor(base, facing = "north", half = "bottom", open = false) {
    return `${idOf(base)}[facing=${facing},half=${half},open=${open}]`;
  }

  function safeSet(x, y, z, block) {
    if (x >= 0 && x < 9 && y >= 0 && y < 28 && z >= 0 && z < 9) {
      api.set(x, y, z, block);
    }
  }

  // Choose timber style based on instance variation
  const mainLog = (varId === 5) ? woodStripped : woodLog;

  // -------------------------------------------------------------
  // 1. STONE PIER FOOTINGS (Rule 6: Ground Following)
  // -------------------------------------------------------------
  const pierBoxes = [
    { x0: 1, x1: 2, z0: 1, z1: 2, postX: 2, postZ: 2, dirX: "west", dirZ: "north" },
    { x0: 6, x1: 7, z0: 1, z1: 2, postX: 6, postZ: 2, dirX: "east", dirZ: "north" },
    { x0: 1, x1: 2, z0: 6, z1: 7, postX: 2, postZ: 6, dirX: "west", dirZ: "south" },
    { x0: 6, x1: 7, z0: 6, z1: 7, postX: 6, postZ: 6, dirX: "east", dirZ: "south" }
  ];

  const pierTopHeights = [];
  const midY = seatY + 6; // y = 13: horizontal ring beam level

  for (let p = 0; p < pierBoxes.length; p++) {
    const pier = pierBoxes[p];
    let maxGround = -999;

    for (let x = pier.x0; x <= pier.x1; x++) {
      for (let z = pier.z0; z <= pier.z1; z++) {
        const gy = seatY + api.heightAt(x, z);
        if (gy > maxGround) maxGround = gy;
      }
    }

    const pierTop = Math.max(seatY + 1, Math.min(midY - 2, maxGround));
    pierTopHeights.push(pierTop);

    for (let x = pier.x0; x <= pier.x1; x++) {
      for (let z = pier.z0; z <= pier.z1; z++) {
        const gy = seatY + api.heightAt(x, z);
        const colBottom = Math.max(0, gy);

        for (let y = colBottom; y <= pierTop; y++) {
          let b = stonePrimary;
          if (y === colBottom) {
            b = plinth;
          } else if ((x + y + z) % 2 === 0) {
            b = stoneAccent;
          }
          safeSet(x, y, z, b);
        }

        // Decorative stone collar around the timber leg anchor
        if (x !== pier.postX || z !== pier.postZ) {
          const facing = (x !== pier.postX) ? pier.dirX : pier.dirZ;
          safeSet(x, pierTop, z, getStair(stoneStairs, facing, "bottom"));
        } else {
          safeSet(x, pierTop, z, stonePrimary);
        }
      }
    }
  }

  // -------------------------------------------------------------
  // 2. TIMBER A-FRAME LOWER LEGS & CROSS-BRACING
  // -------------------------------------------------------------
  const lowerPosts = [
    { x: 2, z: 2, topY: pierTopHeights[0] },
    { x: 6, z: 2, topY: pierTopHeights[1] },
    { x: 2, z: 6, topY: pierTopHeights[2] },
    { x: 6, z: 6, topY: pierTopHeights[3] }
  ];

  for (let i = 0; i < lowerPosts.length; i++) {
    const lp = lowerPosts[i];
    for (let y = lp.topY + 1; y <= midY; y++) {
      safeSet(lp.x, y, lp.z, getLog(mainLog, "y"));
    }
  }

  // Lower horizontal sway ties
  const tieY = seatY + 3;
  for (let x = 3; x <= 5; x++) {
    safeSet(x, tieY, 2, getLog(mainLog, "x"));
    safeSet(x, tieY, 6, getLog(mainLog, "x"));
  }
  for (let z = 3; z <= 5; z++) {
    safeSet(2, tieY, z, getLog(mainLog, "z"));
    safeSet(6, tieY, z, getLog(mainLog, "z"));
  }

  // Diagonal sway braces on lower frame
  safeSet(2, tieY - 1, 3, woodFence);
  safeSet(2, tieY + 1, 5, woodFence);
  safeSet(6, tieY - 1, 5, woodFence);
  safeSet(6, tieY + 1, 3, woodFence);

  safeSet(3, tieY - 1, 2, woodFence);
  safeSet(5, tieY + 1, 2, woodFence);
  safeSet(5, tieY - 1, 6, woodFence);
  safeSet(3, tieY + 1, 6, woodFence);

  // -------------------------------------------------------------
  // 3. MID-LEVEL TRANSITION RING & INWARD TAPER
  // -------------------------------------------------------------
  for (let x = 2; x <= 6; x++) {
    safeSet(x, midY, 2, getLog(mainLog, "x"));
    safeSet(x, midY, 6, getLog(mainLog, "x"));
  }
  for (let z = 2; z <= 6; z++) {
    safeSet(2, midY, z, getLog(mainLog, "z"));
    safeSet(6, midY, z, getLog(mainLog, "z"));
  }

  // Knee transition blocks to the tapered inner posts
  safeSet(3, midY, 3, woodPlanks);
  safeSet(5, midY, 3, woodPlanks);
  safeSet(3, midY, 5, woodPlanks);
  safeSet(5, midY, 5, woodPlanks);

  safeSet(2, midY, 3, getStair(woodStairs, "east", "top"));
  safeSet(6, midY, 3, getStair(woodStairs, "west", "top"));
  safeSet(2, midY, 5, getStair(woodStairs, "east", "top"));
  safeSet(6, midY, 5, getStair(woodStairs, "west", "top"));

  // -------------------------------------------------------------
  // 4. UPPER TAPERED SHAFT (y = midY + 1 to seatY + 13)
  // -------------------------------------------------------------
  const headY = seatY + 13; // y = 20: sheave crossarm level

  for (let y = midY + 1; y <= headY; y++) {
    safeSet(3, y, 3, getLog(mainLog, "y"));
    safeSet(5, y, 3, getLog(mainLog, "y"));
    safeSet(3, y, 5, getLog(mainLog, "y"));
    safeSet(5, y, 5, getLog(mainLog, "y"));
  }

  // Mid-shaft cross-ring at y = seatY + 10
  const upperTieY = seatY + 10;
  safeSet(4, upperTieY, 3, getLog(mainLog, "x"));
  safeSet(4, upperTieY, 5, getLog(mainLog, "x"));
  safeSet(3, upperTieY, 4, getLog(mainLog, "z"));
  safeSet(5, upperTieY, 4, getLog(mainLog, "z"));

  // X-bracing with timber fences
  safeSet(4, upperTieY - 1, 3, woodFence);
  safeSet(4, upperTieY + 1, 3, woodFence);
  safeSet(4, upperTieY - 1, 5, woodFence);
  safeSet(4, upperTieY + 1, 5, woodFence);
  safeSet(3, upperTieY - 1, 4, woodFence);
  safeSet(3, upperTieY + 1, 4, woodFence);
  safeSet(5, upperTieY - 1, 4, woodFence);
  safeSet(5, upperTieY + 1, 4, woodFence);

  // Maintenance ladders
  for (let y = seatY + 2; y <= midY; y++) {
    safeSet(2, y, 1, "minecraft:ladder[facing=north]");
  }
  for (let y = midY + 1; y <= headY; y++) {
    safeSet(3, y, 2, "minecraft:ladder[facing=north]");
  }

  // -------------------------------------------------------------
  // 5. TOP CROSSARM & CANTILEVER SHEAVE HEADFRAME
  // -------------------------------------------------------------
  // Transverse heavy crossarm spanning full width X = 0..8 at Z = 4
  for (let x = 0; x <= 8; x++) {
    safeSet(x, headY, 4, getLog(mainLog, "x"));
  }

  // Framing ties connecting the 4 inner posts to the crossarm
  safeSet(3, headY, 3, getLog(mainLog, "z"));
  safeSet(5, headY, 3, getLog(mainLog, "z"));
  safeSet(3, headY, 5, getLog(mainLog, "z"));
  safeSet(5, headY, 5, getLog(mainLog, "z"));

  safeSet(4, headY, 3, woodPlanks);
  safeSet(4, headY, 5, woodPlanks);
  safeSet(3, headY, 4, woodPlanks);
  safeSet(5, headY, 4, woodPlanks);
  safeSet(4, headY, 4, woodPlanks);

  // Cantilever knee braces under the extended crossarm wings
  safeSet(1, headY - 1, 4, getStair(woodStairs, "east", "top"));
  safeSet(2, headY - 1, 4, getStair(woodStairs, "east", "bottom"));
  safeSet(6, headY - 1, 4, getStair(woodStairs, "west", "bottom"));
  safeSet(7, headY - 1, 4, getStair(woodStairs, "west", "top"));

  // -------------------------------------------------------------
  // 6. CATWALK & APEX ROOF TRUSS
  // -------------------------------------------------------------
  const deckY = headY + 1; // y = 21

  // Catwalk decking
  for (let x = 2; x <= 6; x++) {
    for (let z = 3; z <= 5; z++) {
      if (x === 3 && z === 3) {
        safeSet(x, deckY, z, getTrapdoor(woodTrapdoor, "north", "bottom", true));
      } else {
        safeSet(x, deckY, z, woodPlanks);
      }
    }
  }

  // Safety railings around catwalk perimeter
  safeSet(2, deckY + 1, 3, woodFence);
  safeSet(2, deckY + 1, 5, woodFence);
  safeSet(6, deckY + 1, 3, woodFence);
  safeSet(6, deckY + 1, 5, woodFence);
  safeSet(3, deckY + 1, 5, woodFence);
  safeSet(4, deckY + 1, 5, woodFence);
  safeSet(5, deckY + 1, 5, woodFence);
  safeSet(4, deckY + 1, 3, woodFence);
  safeSet(5, deckY + 1, 3, woodFence);

  // Upper peaked gable ridge truss
  safeSet(3, deckY + 1, 4, getStair(woodStairs, "east", "bottom"));
  safeSet(4, deckY + 1, 4, getLog(mainLog, "z"));
  safeSet(5, deckY + 1, 4, getStair(woodStairs, "west", "bottom"));
  safeSet(4, deckY + 2, 4, getSlab(woodSlab, "bottom"));

  // Inspection lantern hanging beneath center crossarm
  safeSet(4, headY - 1, 4, "minecraft:lantern[hanging=true]");

  // Catwalk detail: oil barrel or supply chest
  if (varId === 2 || varId === 4) {
    safeSet(5, deckY + 1, 4, "minecraft:barrel[facing=up]");
  }

  // -------------------------------------------------------------
  // 7. TRAMWAY TRACK CABLES & SHEAVE WHEELS (West X=1, East X=7)
  // -------------------------------------------------------------
  // Continuous track cable spanning north-south
  for (let z = 0; z <= 8; z++) {
    if (z !== 4) {
      safeSet(1, headY, z, "minecraft:chain[axis=z]");
      safeSet(7, headY, z, "minecraft:chain[axis=z]");
    }
  }

  // Sheave pulleys on crossarm
  safeSet(1, headY + 1, 4, "minecraft:grindstone[face=floor,facing=north]");
  safeSet(7, headY + 1, 4, "minecraft:grindstone[face=floor,facing=north]");

  // Cable guide roller guards
  safeSet(1, headY + 1, 3, "minecraft:iron_bars");
  safeSet(1, headY + 1, 5, "minecraft:iron_bars");
  safeSet(7, headY + 1, 3, "minecraft:iron_bars");
  safeSet(7, headY + 1, 5, "minecraft:iron_bars");

  // Secondary haulage rope slightly lower
  for (let z = 0; z <= 8; z++) {
    if (z !== 4) {
      safeSet(1, headY - 1, z, "minecraft:chain[axis=z]");
      safeSet(7, headY - 1, z, "minecraft:chain[axis=z]");
    }
  }

  // -------------------------------------------------------------
  // 8. SUSPENDED ORE BUCKETS (Instance Variant Driven)
  // -------------------------------------------------------------
  const oreMaterials = [
    "minecraft:raw_iron_block",
    "minecraft:deepslate_iron_ore",
    "minecraft:iron_ore",
    "minecraft:raw_copper_block",
    "minecraft:raw_iron_block",
    "minecraft:deepslate_iron_ore"
  ];
  const chosenOre = oreMaterials[varId];

  // West side: Loaded bucket travelling down slope
  const westBucketZ = [2, 5, 3, 6, 2, 5][varId];
  safeSet(1, headY, westBucketZ, "minecraft:iron_bars");
  safeSet(1, headY - 1, westBucketZ, "minecraft:chain[axis=y]");
  safeSet(1, headY - 2, westBucketZ, "minecraft:chain[axis=y]");
  safeSet(1, headY - 3, westBucketZ, "minecraft:iron_bars");
  safeSet(1, headY - 4, westBucketZ, "minecraft:hopper[facing=down]");
  safeSet(1, headY - 5, westBucketZ, chosenOre);

  // East side: Returning empty bucket or counterweight
  const hasEastBucket = (varId !== 1 && varId !== 5);
  if (hasEastBucket) {
    const eastBucketZ = [6, 2, 6, 3, 5, 2][varId];
    safeSet(7, headY, eastBucketZ, "minecraft:iron_bars");
    safeSet(7, headY - 1, eastBucketZ, "minecraft:chain[axis=y]");
    safeSet(7, headY - 2, eastBucketZ, "minecraft:chain[axis=y]");
    safeSet(7, headY - 3, eastBucketZ, "minecraft:iron_bars");
    safeSet(7, headY - 4, eastBucketZ, "minecraft:cauldron");
  } else if (varId === 1) {
    // Tension counterweight box on East wing
    safeSet(8, headY - 1, 4, "minecraft:chain[axis=y]");
    safeSet(8, headY - 2, 4, stonePrimary);
    safeSet(8, headY - 3, 4, stoneAccent);
  }

  // Guy wire bracing for high-tension variants
  if (varId === 1 || varId === 3) {
    safeSet(0, headY - 1, 4, "minecraft:chain[axis=y]");
    safeSet(0, headY - 2, 4, "minecraft:iron_bars");
    safeSet(8, headY - 1, 4, "minecraft:chain[axis=y]");
    safeSet(8, headY - 2, 4, "minecraft:iron_bars");
  }

  return {
    name: "ore_tramway_pylon",
    seatY: seatY,
    anchors: {
      front: [4, seatY, 0],
      sheave_west: [1, headY, 4],
      sheave_east: [7, headY, 4],
      catwalk: [4, deckY, 4]
    }
  };
}
